// expect: exit 0
// screen: 0 abcd 4
// screen: 1 Leap-C ok
char buf[16];
int main(void)
{
    char *s = "ab" "cd";
    cls();
    printf("%s %d\n", s, strlen(s));
    strcpy(buf, "Leap");
    strcat(buf, "-C");
    printf("%s %s\n", buf, strcmp(buf, "Leap-C") == 0 ? "ok" : "no");
    return buf[4] != '-';
}
